const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binKeys = Object.keys(item.binary || {});
  if (binKeys.length === 0) {
    throw new Error('No screenshot file received. Please upload an image.');
  }
  const binKey = binKeys[0];
  const file = item.binary[binKey];
  const mime = (file.mimeType || 'image/png').toLowerCase();
  if (mime.indexOf('image/') !== 0) {
    throw new Error('Uploaded file is not an image (detected type: ' + mime + ').');
  }
  const buffer = await this.helpers.getBinaryDataBuffer(i, binKey);
  const b64 = buffer.toString('base64');
  const approxBytes = buffer.length;
  if (approxBytes > 19 * 1024 * 1024) {
    throw new Error('Screenshot is larger than 19 MB. Groq accepts up to 20 MB per image. Please upload a smaller image.');
  }
  let errorLogs = '';
  const json = item.json || {};
  for (const key of Object.keys(json)) {
    const value = json[key];
    if (typeof value === 'string' && value.trim() !== '' && key !== 'submittedAt' && key !== 'headers') {
      errorLogs = value;
      break;
    }
  }
  const ext = (mime.split('/')[1] || 'png').replace('jpeg', 'jpg');
  const fileName = file.fileName || ('screenshot.' + ext);
  const imageB64 = b64;
  const dataUri = 'data:' + mime + ';base64,' + b64;
  const SYSTEM_PROMPT = [
    'You are a meticulous senior QA engineer. A tester uploads a screenshot of a UI bug',
    'and optionally some error logs. Analyze the image carefully and produce a complete',
    'bug report as JSON ONLY (no markdown fences, no extra text).',
    'Return valid JSON with EXACTLY these keys:',
    '  summary          : string  - concise bug title (max ~12 words).',
    '  severity         : string  - one of Blocker, Critical, Major, Minor, Trivial.',
    '  component        : string  - the UI area or feature most likely affected, or null if unclear.',
    '  environment      : string  - browser/OS/device you can infer, or null if unclear.',
    '  visualDetails    : string  - describe exactly what is visibly wrong: layout, colors, missing or wrong text.',
    '  expectedBehavior : string  - what should have happened.',
    '  actualBehavior   : string  - what actually happened.',
    '  stepsToReproduce : array of strings - ordered, concrete steps (3 to 6).',
    '  errorLogs        : string  - the logs pasted by the tester, or null if none.',
    'Do NOT invent details that are not visible in the screenshot. Quote any on-screen error text verbatim.'
  ].join('\n');
  const logSection = errorLogs.trim() !== '' ? (' Error logs provided by tester:\n' + errorLogs) : '';
  const USER_PROMPT = 'Analyze this UI screenshot and write the bug report as JSON.' + logSection;
  out.push({
    json: {
      fileName: fileName,
      mimeType: mime,
      imageB64: imageB64,
      dataUri: dataUri,
      errorLogs: errorLogs,
      GROQ_MODEL: 'qwen/qwen3.8-27b',
      JIRA_BASE_URL: 'https://YOUR-DOMAIN.atlassian.net',
      SYSTEM_PROMPT: SYSTEM_PROMPT,
      USER_PROMPT: USER_PROMPT
    }
  });
}
return out;

const items = $input.all();
const out = [];
for (const item of items) {
  const json = item.json || {};
  let content = '';
  try {
    content = (json.choices && json.choices[0] && json.choices[0].message && json.choices[0].message.content) || '';
  } catch (err) {
    throw new Error('Unexpected Groq response shape.');
  }
  if (content === '') {
    throw new Error('Groq returned an empty answer. ' + JSON.stringify(json));
  }
  let bug = null;
  try {
    bug = JSON.parse(content);
  } catch (err) {
    throw new Error('AI did not return valid JSON. Got: ' + content.slice(0, 300));
  }
  const steps = Array.isArray(bug.stepsToReproduce) ? bug.stepsToReproduce : [];
  const summary = (bug.summary || 'Bug reported from screenshot').trim();
  const adf = { version: 1, type: 'doc', content: [] };
  function textPara(text) {
    return { type: 'paragraph', content: [{ type: 'text', text: String(text || '') }] };
  }
  function heading(level, text) {
    return { type: 'heading', attrs: { level: level }, content: [{ type: 'text', text: String(text || '') }] };
  }
  function rule() {
    return { type: 'rule' };
  }
  adf.content.push(heading(1, summary));
  adf.content.push(rule());
  adf.content.push(heading(2, 'Environment'));
  adf.content.push(textPara(bug.environment || 'Not specified'));
  adf.content.push(rule());
  adf.content.push(heading(2, 'Visual details'));
  adf.content.push(textPara(bug.visualDetails || 'See attached screenshot.'));
  adf.content.push(rule());
  adf.content.push(heading(2, 'Steps to reproduce'));
  if (steps.length > 0) {
    steps.forEach(function (step, idx) {
      adf.content.push(textPara(String(idx + 1) + '. ' + String(step)));
    });
  } else {
    adf.content.push(textPara('Not provided.'));
  }
  adf.content.push(rule());
  adf.content.push(heading(2, 'Expected behavior'));
  adf.content.push(textPara(bug.expectedBehavior || 'Not specified'));
  adf.content.push(heading(2, 'Actual behavior'));
  adf.content.push(textPara(bug.actualBehavior || 'Not specified'));
  if (bug.errorLogs) {
    adf.content.push(heading(2, 'Error logs'));
    adf.content.push(textPara(String(bug.errorLogs)));
  }
  out.push({
    json: {
      summary: summary,
      severity: bug.severity || 'Major',
      component: bug.component || null,
      environment: bug.environment || null,
      stepsToReproduce: steps,
      visualDetails: bug.visualDetails || '',
      expectedBehavior: bug.expectedBehavior || '',
      actualBehavior: bug.actualBehavior || '',
      errorLogs: bug.errorLogs || '',
      descriptionAdfJson: JSON.stringify(adf)
    }
  });
}
return out;

