const items = $input.all();
const out = [];
for (const item of items) {
  const json = item.json || {};
  const issueKey = json.key || '';
  if (issueKey === '') {
    throw new Error('Could not read the created issue key from Jira.');
  }
  const base = json.JIRA_BASE_URL || 'https://your-domain.atlassian.net';
  const issueUrl = base + '/browse/' + issueKey;
  out.push({
    json: {
      issueKey: issueKey,
      issueUrl: issueUrl,
      message: 'Bug created in Jira: ' + issueKey
    },
    binary: {
      data: {
        data: json.imageB64 || '',
        mimeType: json.mimeType || 'image/png',
        fileName: json.fileName || 'screenshot.png'
      }
    }
  });
}
return out;
